sys_variable_value.value:
(function execute(inputs, outputs) {
    const ticket_map = {
        1: 'new',
        2: 'in_progress',
        3: 'on_hold',
        6: 'resolved',
        7: 'closed',
        8: 'canceled'
    }
    outputs.is_echo = ticket_map[parseInt(inputs.incident_state, 10)] == String(inputs.odee_ticket_state);
})(inputs, outputs);

